/**
 * Client-side DFA simulator. Mirrors simulator_service.php domain logic.
 *
 * v1: minimal — accepts/rejects + returns state trace as array.
 * Transition map key format: "stateId:symbol".
 *
 * @module     mod_graphitoubb/afd_simulator
 * @copyright  2026 GraphitoUBB
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define([],function(){return{run:function(t,e){for(var n=t.initialState,r=[n],a=e.split(""),i=0;i<a.length;i++){var c=n+":"+a[i];if(!Object.prototype.hasOwnProperty.call(t.transitions,c))return{accepted:!1,trace:r};n=t.transitions[c],r.push(n)}return{accepted:-1!==t.acceptStates.indexOf(n),trace:r}}}});